const crypto=require('crypto');
const ALPHA='123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
function b58encode(buf){
  let zeros=0; while(zeros<buf.length&&buf[zeros]===0)zeros++;
  let n=0n; for(const b of buf)n=n*256n+BigInt(b);
  let s=''; while(n>0n){s=ALPHA[Number(n%58n)]+s;n/=58n;}
  return '1'.repeat(zeros)+s;
}
function b58decode(str){
  let zeros=0; while(zeros<str.length&&str[zeros]==='1')zeros++;
  let n=0n; for(const ch of str){const i=ALPHA.indexOf(ch); if(i<0)throw new Error('bad char '+ch); n=n*58n+BigInt(i);}
  const bytes=[]; while(n>0n){bytes.unshift(Number(n%256n)); n/=256n;}
  return Buffer.concat([Buffer.alloc(zeros), Buffer.from(bytes)]);
}
const h=(alg,b)=>crypto.createHash(alg).update(b).digest();
module.exports={ALPHA,b58encode,b58decode,h};
